package com.optarena.app

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertThrows
import org.junit.jupiter.api.Test

class RomanNumeralTest {

    @Test
    fun simpleValues() {
        assertEquals("I", RomanNumeral.format(1))
        assertEquals("V", RomanNumeral.format(5))
        assertEquals("X", RomanNumeral.format(10))
    }

    @Test
    fun subtractivePairs() {
        assertEquals("IV", RomanNumeral.format(4))
        assertEquals("IX", RomanNumeral.format(9))
        assertEquals("XC", RomanNumeral.format(90))
        assertEquals("CM", RomanNumeral.format(900))
    }

    @Test
    fun compoundValue() {
        assertEquals("MCMXCIV", RomanNumeral.format(1994))
    }

    @Test
    fun boundaryValues() {
        assertEquals("MMMCMXCIX", RomanNumeral.format(3999))
    }

    @Test
    fun outOfRangeThrows() {
        assertThrows(IllegalArgumentException::class.java) { RomanNumeral.format(0) }
        assertThrows(IllegalArgumentException::class.java) { RomanNumeral.format(4000) }
    }
}

