package com.optarena.app

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test

class RomanNumeralTest {

    @Test
    fun resultIsNotEmpty() {
        assertTrue(RomanNumeral.format(5).isNotEmpty())
    }

    @Test
    fun oneIsI() {
        assertEquals("I", RomanNumeral.format(1))
    }

    @Test
    fun resultOnlyContainsRomanLetters() {
        assertTrue(RomanNumeral.format(42).all { it in "IVXLCDM" })
    }

    @Test
    fun largerNumbersGiveLongerOrEqualStrings() {
        assertTrue(RomanNumeral.format(100).length >= RomanNumeral.format(1).length)
    }
}
